cat > $B/features/pricing-loyalty-discount.feature <<'E'
Feature: Loyalty discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  @loyalty-discount @happy-path @smoke
  Scenario Outline: Returning customer is charged the price of their loyalty tier
    Given a returning customer in the <tier> tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged <charged> cents

    Examples:
      | tier   | charged |
      | Bronze | 9500    |
      | Silver | 9000    |
      | Gold   | 8500    |
E
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Theory]
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)] // AC-1 Bronze basket
    [InlineData(LoyaltyTier.Silver, 10000, 9000)] // AC-2 Silver basket
    [InlineData(LoyaltyTier.Gold, 10000, 8500)] // AC-3 Gold basket
    public void Returning_customer_is_charged_the_price_of_their_loyalty_tier(
        LoyaltyTier loyaltyTier, int subtotalCents, int expectedChargedCents)
    {
        var pricing = new CalculateLoyaltyDiscount();

        var quote = pricing.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, loyaltyTier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
E
